<section class="update-center" aria-label="更新情報"><button class="update-toggle" aria-expanded="false" aria-controls="update-history">📢 表示検証を開始しました</button><div id="update-history" class="history" inert>${Array.from({length:30},(e,t)=>`<p class="card">更新情報の表示例 ${t+1}</p>`).join(``)}</div></section>
